SELECT COUNT(DISTINCT a.subject_id) AS N, AVG(EXTRACT(YEAR FROM a.dischtime - a.admittime)) AS average_length_of_stay, AVG(a.los) AS average_length_of_icu_stay, SUM(CASE WHEN l.value > percentile_cont(0.99) THEN 1 ELSE 0 END) AS high_troponin_count FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dod)) BETWEEN 83 AND 93 AND l.itemid = 811071 AND l.value > percentile_cont(0.99) GROUP BY a.subject_id;